"const { default: makeWASocket, useMultiFileAuthState, DisconnectReason } = require('@whiskeysockets/baileys');
const pino = require('pino');
const path = require('path');
const fs = require('fs');

let sock = null;

async function startWhatsApp(io) {
    const authDir = path.join(__dirname, '..', 'auth_info_baileys');
    const { state, saveCreds } = await useMultiFileAuthState(authDir);

    sock = makeWASocket({
        auth: state,
        printQRInTerminal: true,
        logger: pino({ level: 'silent' }), // Suppress heavy logs
        browser: ['Chatpay', 'Chrome', '1.0.0']
    });

    sock.ev.on('creds.update', saveCreds);

    sock.ev.on('connection.update', (update) => {
        const { connection, lastDisconnect, qr } = update;

        if (qr) {
            console.log('Got QR Code, emitting to frontend...');
            io.emit('qr', qr);
        }

        if (connection === 'close') {
            const shouldReconnect = (lastDisconnect.error)?.output?.statusCode !== DisconnectReason.loggedOut;
            console.log('Connection closed due to ', lastDisconnect.error, ', reconnecting ', shouldReconnect);

            if (shouldReconnect) {
                startWhatsApp(io);
            } else {
                console.log('Logged out. Please delete auth_info_baileys and restart to scan again.');
                io.emit('disconnected', 'Logged out');
                // Optionally delete auth folder here
                fs.rmSync(authDir, { recursive: true, force: true });
                startWhatsApp(io);
            }
        } else if (connection === 'open') {
            console.log('WhatsApp connection is open!');
            io.emit('authenticated', 'Connection open');
        }
    });

    return sock;
}

function getSock() {
    return sock;
}

module.exports = { startWhatsApp, getSock };
"

"const { default: makeWASocket, useMultiFileAuthState, DisconnectReason } = require('@whiskeysockets/baileys');
const pino = require('pino');
const path = require('path');
const fs = require('fs');

let sock = null;

async function startWhatsApp(io) {
    const authDir = path.join(__dirname, '..', 'auth_info_baileys');
    const { state, saveCreds } = await useMultiFileAuthState(authDir);

    sock = makeWASocket({
        auth: state,
        printQRInTerminal: true,
        logger: pino({ level: 'silent' }), // Suppress heavy logs
        browser: ['Chatpay', 'Chrome', '1.0.0']
    });

    sock.ev.on('creds.update', saveCreds);

    sock.ev.on('connection.update', (update) => {
        const { connection, lastDisconnect, qr } = update;

        if (qr) {
            console.log('Got QR Code, emitting to frontend...');
            io.emit('qr', qr);
        }

        if (connection === 'close') {
            const shouldReconnect = (lastDisconnect?.error)?.output?.statusCode !== DisconnectReason.loggedOut;
            console.log('Connection closed due to ', lastDisconnect?.error, ', reconnecting: ', shouldReconnect);

            if (shouldReconnect) {
                setTimeout(() => startWhatsApp(io), 2000);
            } else {
                console.log('Logged out. Deleting auth folder to restart session.');
                io.emit('disconnected', 'Logged out');
                try {
                    fs.rmSync(authDir, { recursive: true, force: true });
                } catch(e) {
                    console.error('Failed to delete auth dir', e);
                }
                setTimeout(() => startWhatsApp(io), 2000);
            }
        } else if (connection === 'open') {
            console.log('WhatsApp connection is open!');
            io.emit('authenticated', 'Connection open');
        }
    });

    return sock;
}

function getSock() {
    return sock;
}

module.exports = { startWhatsApp, getSock };
